43	// 1) iterate over all remaining active vertices
44	// 2) for each active vertex, remove if induced degree < k. Any vertex removed has
45	//    core-number (k-1) (part of (k-1)-core, but not k-core)
46	// 3) stop once no vertices are removed. Vertices remaining are in the k-core.
47	template <class vertex>
48	void Compute(graph<vertex>& GA, commandLine P) {
49	  const long n = GA.n;
50	  bool* active = newA(bool,n);
51	  {parallel_for(long i=0;i<n;i++) active[i] = 1;}
52	  vertexSubset Frontier(n, n, active);
53	  long* coreNumbers = new long[n];
54	  long* Degrees = new long[n];
55	  {parallel_for(long i=0;i<n;i++) {
56	      coreNumbers[i] = 0;
57	      Degrees[i] = GA.V[i].getOutDegree();
58	    }}
59	  long largestCore = -1;
60	  for (long k = 1; k <= n; k++) {
61	    while (true) {
62	      vertexSubset toRemove 
63		= vertexFilter(Frontier,Deg_LessThan_K<vertex>(GA.V,Degrees,coreNumbers,k));
64	      vertexSubset remaining = vertexFilter(Frontier,Deg_AtLeast_K<vertex>(GA.V,Degrees,k));
65	      Frontier.del();
66	      Frontier = remaining;
67	      if (0 == toRemove.numNonzeros()) { // fixed point. found k-core
68		toRemove.del();
69	        break;
70	      }
71	      else {
72		vertexSubset output = edgeMap(GA,toRemove,Update_Deg(Degrees));
73		toRemove.del(); output.del();
74	      }
75	    }
76	    if(Frontier.numNonzeros() == 0) { largestCore = k-1; break; }
77	  }
78	  cout << "largestCore was " << largestCore << endl;
79	  Frontier.del(); free(coreNumbers); free(Degrees);
80	}
