// k-core decomposition by peeling.  Assumes a symmetric graph.
//
// Degrees[v] holds the degree of v in the graph induced by the vertices that
// have not been peeled off yet, and is set to 0 once v is removed.  For
// k = 1, 2, ... we repeatedly remove every remaining vertex whose induced
// degree is below k; each such vertex belongs to the (k-1)-core but not to the
// k-core, so its core number is k-1.  Once a round removes nothing we have
// reached a fixed point (the remaining vertices form the k-core) and move on to
// k+1.  The largest core number is k-1 for the first k whose core is empty.
#include "ligra.h"

// Decrements the induced degree of each neighbor of a peeled vertex. cond stops
// the decrementing once a vertex reaches degree 0, so degrees never go
// negative: a vertex at 0 has already been (or is about to be) peeled.
struct Update_Deg {
  intE* Degrees;
  Update_Deg(intE* _Degrees) : Degrees(_Degrees) {}
  inline bool update (uintE s, uintE d) {
    Degrees[d]--;
    return 1;
  }
  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
    writeAdd(&Degrees[d],(intE)-1);
    return 1;
  }
  inline bool cond (uintE d) { return Degrees[d] > 0; }
};

// Selects the vertices to peel in this round: those whose induced degree has
// dropped below k. Removing a vertex here records its core number (k-1) and
// zeroes its degree so that it is excluded from the remaining subset and from
// any further decrements.
template <class vertex>
struct Deg_LessThan_K {
  vertex* V;
  uintE* coreNumbers;
  intE* Degrees;
  long k;
  Deg_LessThan_K(vertex* _V, intE* _Degrees, uintE* _coreNumbers, long _k) :
    V(_V), k(_k), Degrees(_Degrees), coreNumbers(_coreNumbers) {}
  inline bool operator () (uintE i) {
    if(Degrees[i] < k) { coreNumbers[i] = k-1; Degrees[i] = 0; return 1; }
    else return 0;
  }
};

// Selects the vertices that survive this round, i.e. the ones still having
// induced degree at least k. Peeled vertices have degree 0 and so drop out.
template <class vertex>
struct Deg_AtLeast_K {
  vertex* V;
  intE* Degrees;
  long k;
  Deg_AtLeast_K(vertex* _V, intE* _Degrees, long _k) :
    V(_V), k(_k), Degrees(_Degrees) {}
  inline bool operator () (uintE i) {
    return Degrees[i] >= k;
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  const long n = GA.n;
  //the frontier holds the vertices not yet peeled; initially all of them
  bool* active = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) active[i] = 1;}
  vertexSubset Frontier(n, n, active);

  uintE* coreNumbers = newA(uintE,n);
  intE* Degrees = newA(intE,n);
  {parallel_for(long i=0;i<n;i++) {
      coreNumbers[i] = 0;
      Degrees[i] = GA.V[i].getOutDegree();
    }}

  long largestCore = -1;
  for (long k = 1; k <= n; k++) {
    while (true) {
      //vertices with induced degree < k are peeled off with core number k-1
      vertexSubset toRemove
	= vertexFilter(Frontier,Deg_LessThan_K<vertex>(GA.V,Degrees,coreNumbers,k));
      //the rest stay for the next round (this must run after the filter above,
      //which zeroes the degrees of the peeled vertices)
      vertexSubset remaining = vertexFilter(Frontier,Deg_AtLeast_K<vertex>(GA.V,Degrees,k));
      Frontier.del();
      Frontier = remaining;
      if (0 == toRemove.numNonzeros()) { //fixed point: found the k-core
	toRemove.del();
	break;
      }
      else { //update the induced degrees of the neighbors of the peeled vertices
	edgeMap(GA,toRemove,Update_Deg(Degrees),-1,no_output);
	toRemove.del();
      }
    }
    if (Frontier.numNonzeros() == 0) { largestCore = k-1; break; }
  }

  cout << "largestCore was " << largestCore << endl;
  cout << "KCore max core: " << largestCore << endl;

  Frontier.del(); free(coreNumbers); free(Degrees);
}

